"""Copy every payout from the Tallyline Payouts API into payouts.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.parse
import urllib.request

PAGE_LIMIT = 1000


class InvalidCursor(Exception):
    """The API rejected our cursor; the export must start over."""


def get_json(url):
    """GET url, retrying the identical request on 429 responses."""
    while True:
        try:
            with urllib.request.urlopen(url, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            if e.code == 429:
                retry_after = e.headers.get("Retry-After")
                try:
                    delay = max(0.0, float(retry_after))
                except (TypeError, ValueError):
                    delay = 1.0
                e.close()
                time.sleep(delay)
                continue
            if e.code == 400:
                try:
                    body = json.load(e)
                except Exception:
                    body = {}
                finally:
                    e.close()
                if body.get("error") == "invalid_cursor":
                    raise InvalidCursor()
            raise


def fetch_payouts(base_url):
    """Export all payouts, following cursors until the export is drained.

    Windows overlap, so payouts are deduplicated on their unique id.
    """
    endpoint = f"{base_url}/v2/payouts"
    seen = set()
    payouts = []
    cursor = None

    while True:
        params = {"limit": PAGE_LIMIT}
        if cursor is not None:
            params["cursor"] = cursor
        url = f"{endpoint}?{urllib.parse.urlencode(params)}"

        try:
            data = get_json(url)
        except InvalidCursor:
            # Rejected cursor: restart the export from the first payout.
            # Deduplication on id keeps the restart from writing duplicates.
            cursor = None
            continue

        for payout in data["payouts"]:
            payout_id = payout["id"]
            if payout_id not in seen:
                seen.add(payout_id)
                payouts.append(payout)

        if data["drained"]:
            break

        cursor = data["cursor"]
        if not cursor:
            break

    return payouts


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="payouts.jsonl")
    args = ap.parse_args()
    payouts = fetch_payouts(args.base_url.rstrip("/"))
    with open(args.out, "w") as f:
        for p in payouts:
            f.write(json.dumps(p) + "\n")
    print(f"synced {len(payouts)} payouts")


if __name__ == "__main__":
    main()

